/// Who a request is from: the loopback page (the session token), or a
/// paired LAN device.
#[derive(Clone, Copy)]
enum Session<'a> {
    Loopback,
    Device(&'a Lan, &'a pairing::Device),
}

/// One parsed request.
struct Request {
    method: String,
    path: String,
    headers: Vec<(String, String)>,
    body: Vec<u8>,
